/// Error returned when a required actor index is `None`.
fn nre() -> mlua::Error { rt_err("Object reference not set to an instance of an object.") }

// ---- node creators for the mission logic nodes (also used through register_generated for every script)
pub fn logic_start(st: &mut ScriptState, note: Option<String>, r: i32, g: i32, b: i32) -> LuaResult<(usize, usize)> {
    let color = node_color(r as f64, g as f64, b as f64, 255 as f64);
    Ok(st.create_node(1, note.as_deref(), color, 0, |st| vec![

    ]))
}

pub fn truck_delivery_control(st: &mut ScriptState, truck: Option<usize>, car1: Option<usize>, car2: Option<usize>, car3: Option<usize>, compound: Option<usize>, wrongCarTextId: i32, distanceText: i32, kilometerText: i32, mileText: i32, note: Option<String>, r: i32, g: i32, b: i32) -> LuaResult<(usize, usize)> {
    if st.logic.actors.definitions[truck.ok_or_else(nre)?].type_id != 3 { return Err(rt_err("Bad Argument #1 - The truck actor type is not a Vehicle actor type")); }
    if st.logic.actors.definitions[car1.ok_or_else(nre)?].type_id != 3 { return Err(rt_err("Bad Argument #2 - The car #1 actor type is not a Vehicle actor type")); }
    if st.logic.actors.definitions[car2.ok_or_else(nre)?].type_id != 3 { return Err(rt_err("Bad Argument #3 - The car #2 actor type is not a Vehicle actor type")); }
    if st.logic.actors.definitions[car3.ok_or_else(nre)?].type_id != 3 { return Err(rt_err("Bad Argument #4 - The car #3 actor type is not a Vehicle actor type")); }
    if compound.is_none() { return Err(rt_err("Bad Argument #5 - A actor to the compound position is required")); }
    let color = node_color(r as f64, g as f64, b as f64, 255 as f64);
    let truck_i = truck.ok_or_else(nre)? as i32;
    let car1_i = car1.ok_or_else(nre)? as i32;
    let car2_i = car2.ok_or_else(nre)? as i32;
    let car3_i = car3.ok_or_else(nre)? as i32;
    let compound_i = compound.ok_or_else(nre)? as i32;
    Ok(st.create_node(130, note.as_deref(), color, 0, |st| vec![
            st.prop("pTruck", 7, PropValue::Int(truck_i)),
            st.prop("pCar1", 7, PropValue::Int(car1_i)),
            st.prop("pCar2", 7, PropValue::Int(car2_i)),
            st.prop("pCar3", 7, PropValue::Int(car3_i)),
            st.prop("pCompound", 7, PropValue::Int(compound_i)),
            st.prop("pWrongCarText", 20, PropValue::Int(wrongCarTextId)),
            st.prop("pDistanceText", 20, PropValue::Int(distanceText)),
            st.prop("pKilometerText", 20, PropValue::Int(kilometerText)),
            st.prop("pMileText", 20, PropValue::Int(mileText))
    ]))
}

