pub fn dpl_time_control(st: &mut ScriptState, activity: i32, hours: i32, minutes: i32, flags: i32, note: Option<String>, r: i32, g: i32, b: i32) -> LuaResult<(usize, usize)> {
    let color = node_color(r as f64, g as f64, b as f64, 255 as f64);
    Ok(st.create_node(113, note.as_deref(), color, 0, |st| vec![
            st.prop("Activity", 6, PropValue::Int(activity)),
            st.prop("Hours", 1, PropValue::Int(hours)),
            st.prop("Minutes", 1, PropValue::Int(minutes)),
            st.prop("Flags", 9, PropValue::Int(flags))
    ]))
}

pub fn dpl_set_timer(st: &mut ScriptState, interval: f32, flags: i32, note: Option<String>, r: i32, g: i32, b: i32) -> LuaResult<(usize, usize)> {
    let color = node_color(r as f64, g as f64, b as f64, 255 as f64);
    Ok(st.create_node(3, note.as_deref(), color, 0, |st| vec![
            st.prop("Interval", 2, PropValue::Float((interval) as f32)),
            st.prop("Flags", 9, PropValue::Int(flags))
    ]))
}

pub fn dpl_fade_control(st: &mut ScriptState, direction: i32, duration: f32, flags: i32, R: u8, G: u8, B: u8, A: u8, note: Option<String>, r: i32, g: i32, b: i32) -> LuaResult<(usize, usize)> {
    let color = node_color(r as f64, g as f64, b as f64, 255 as f64);
    Ok(st.create_node(112, note.as_deref(), color, 0x1862, |st| vec![
            st.prop("Direction", 6, PropValue::Int(direction)),
            st.prop("Duration", 2, PropValue::Float((duration) as f32)),
            st.prop("Colour", 17, PropValue::Vec4(Vec4 { x: (R) as f32, y: (G) as f32, z: (B) as f32, w: (A) as f32 })),
            st.prop("Flags", 9, PropValue::Int(flags))
    ]))
}

pub fn dpl_set_fade_out(st: &mut ScriptState, duration: f32, flags: i32, R: u8, G: u8, B: u8, A: u8, note: Option<String>, r: i32, g: i32, b: i32) -> LuaResult<(usize, usize)> {
    dpl_fade_control(st, 2_i32, duration, flags, R, G, B, A, note, r, g, b)
}

pub fn dpl_set_fade_in(st: &mut ScriptState, duration: f32, flags: i32, R: u8, G: u8, B: u8, A: u8, note: Option<String>, r: i32, g: i32, b: i32) -> LuaResult<(usize, usize)> {
    dpl_fade_control(st, 1_i32, duration, flags, R, G, B, A, note, r, g, b)
}

pub fn dpl_proximity_check(st: &mut ScriptState, actor1: Option<usize>, actor2: Option<usize>, threshold: f32, checkType: i32, flags: i32, note: Option<String>, r: i32, g: i32, b: i32) -> LuaResult<(usize, usize)> {
    if actor1.is_none() { return Err(rt_err("Bad Argument #1 - Actor expected got nil")); }
    if actor2.is_none() { return Err(rt_err("Bad Argument #2 - Actor expected got nil")); }
    let color = node_color(r as f64, g as f64, b as f64, 255 as f64);
    let actor1_i = actor1.ok_or_else(nre)? as i32;
    let actor2_i = actor2.ok_or_else(nre)? as i32;
    Ok(st.create_node(30, note.as_deref(), color, 0, |st| vec![
            st.prop("First Actor", 7, PropValue::Int(actor1_i)),
            st.prop("Second Actor", 7, PropValue::Int(actor2_i)),
            st.prop("Check Type", 6, PropValue::Int(checkType)),
            st.prop("Threshold", 2, PropValue::Float((threshold) as f32)),
            st.prop("pFlags", 9, PropValue::Int(flags))
    ]))
}

